(function () {
  const specialtySelector = '.crown-specialty-items';
  const uploadSelector = '.crown-photo-upload';

  function injectStyles() {
    if (document.getElementById('crown-specialty-style')) {
      return;
    }

    const style = document.createElement('style');
    style.id = 'crown-specialty-style';
    style.textContent = `
      .crown-specialty-items input[type="checkbox"] {
        accent-color: #fe4b03 !important;
        cursor: pointer !important;
      }

      .crown-specialty-items .crown-specialty-selected {
        background: #fff3ed !important;
        border: 1px solid #fe4b03 !important;
        border-radius: 12px !important;
        padding: 8px 12px !important;
        display: inline-flex !important;
        align-items: center !important;
        gap: 10px !important;
      }

      .crown-photo-recommended-note {
        margin-top: 10px;
        padding: 12px 14px;
        border-radius: 10px;
        background: #fff3ed;
        color: #111111;
        font-weight: 700;
        font-size: 15px;
        line-height: 1.4;
      }
    `;

    document.head.appendChild(style);
  }

  function getOptionText(input) {
    const label = input.closest('label');

    if (label) {
      return label.textContent.trim().toLowerCase();
    }

    const row = input.closest('li, div, p');

    if (row) {
      return row.textContent.trim().toLowerCase();
    }

    return (input.value || '').trim().toLowerCase();
  }

  function isNoneOption(input) {
    const text = getOptionText(input);
    const value = (input.value || '').trim().toLowerCase();

    return text === 'none' || value === 'none';
  }

  function getChoiceElement(input) {
    const label = input.closest('label');

    if (label) {
      return label;
    }

    return input.closest('li, div, p');
  }

  function forceCheckboxes() {
    document.querySelectorAll(`${specialtySelector} input[type="radio"]`).forEach(function (input) {
      input.type = 'checkbox';
    });

    document.querySelectorAll(`${specialtySelector} input[type="checkbox"]`).forEach(function (input) {
      input.removeAttribute('required');
      input.removeAttribute('aria-required');
    });
  }

  function updateSelectedStyles() {
    document.querySelectorAll(`${specialtySelector} input[type="checkbox"]`).forEach(function (input) {
      const choice = getChoiceElement(input);

      if (!choice) {
        return;
      }

      if (input.checked) {
        choice.classList.add('crown-specialty-selected');
      } else {
        choice.classList.remove('crown-specialty-selected');
      }
    });
  }

  function updatePhotoNotice() {
    const uploadWrapper = document.querySelector(uploadSelector);

    if (!uploadWrapper) {
      return;
    }

    let specialtySelected = false;

    document.querySelectorAll(`${specialtySelector} input[type="checkbox"]`).forEach(function (input) {
      if (input.checked && !isNoneOption(input)) {
        specialtySelected = true;
      }
    });

    let note = uploadWrapper.querySelector('.crown-photo-recommended-note');

    if (!note) {
      note = document.createElement('div');
      note.className = 'crown-photo-recommended-note';
      note.innerHTML = 'Photos are strongly recommended for specialty items. You can still submit, but our team may ask for photos before confirming your final quote.';
      uploadWrapper.appendChild(note);
    }

    note.style.display = specialtySelected ? 'block' : 'none';
  }

  function updateAll() {
    forceCheckboxes();
    updateSelectedStyles();
    updatePhotoNotice();
  }

  document.addEventListener('change', function (event) {
    const specialtyInput = event.target.closest(`${specialtySelector} input[type="checkbox"], ${specialtySelector} input[type="radio"]`);

    if (!specialtyInput) {
      updateAll();
      return;
    }

    forceCheckboxes();

    const allInputs = document.querySelectorAll(`${specialtySelector} input[type="checkbox"]`);

    if (isNoneOption(specialtyInput) && specialtyInput.checked) {
      allInputs.forEach(function (input) {
        if (input !== specialtyInput) {
          input.checked = false;
        }
      });
    }

    if (!isNoneOption(specialtyInput) && specialtyInput.checked) {
      allInputs.forEach(function (input) {
        if (isNoneOption(input)) {
          input.checked = false;
        }
      });
    }

    updateAll();
  });

  document.addEventListener('click', function () {
    setTimeout(updateAll, 50);
  });

  document.addEventListener('DOMContentLoaded', function () {
    injectStyles();
    updateAll();

    let runs = 0;

    const timer = setInterval(function () {
      updateAll();
      runs++;

      if (runs >= 20) {
        clearInterval(timer);
      }
    }, 300);

    const observer = new MutationObserver(function () {
      updateAll();
    });

    observer.observe(document.body, {
      childList: true,
      subtree: true
    });
  });

  window.addEventListener('load', function () {
    injectStyles();
    updateAll();
  });
})();

